<?php
/**  * Manager Reports API  * Serves data for all 6 report sections:  *  sales, job_orders, balances, deliveries, staff, validation  */  require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';  header('Content-Type: application/json');
require_login();  $me  = current_user();
$role  = role_key($me['role'] ?? '');
$station_id = user_station_id();  // Allow manager, admin, superadmin
if (!in_array($role, ['manager', 'admin', 'superadmin', 'super admin'])) {  http_response_code(403);  echo json_encode(['ok' => false, 'error' => 'Access denied.']);  exit;
}  $action = $_GET['action'] ?? $_POST['action'] ?? '';  // ── Date range helpers ────────────────────────────────────────────────────
$date_from = $_GET['date_from'] ?? $_POST['date_from'] ?? date('Y-m-01');
$date_to  = $_GET['date_to']  ?? $_POST['date_to']  ?? date('Y-m-d');  // Sanitize dates
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from)) $date_from = date('Y-m-01');
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to))  $date_to  = date('Y-m-d');  function ok($data) {  echo json_encode(['ok' => true, 'data' => $data]);  exit;
}
function err($msg, $code = 400) {  http_response_code($code);  echo json_encode(['ok' => false, 'error' => $msg]);  exit;
}  try {  switch ($action) {  // ── 1. SALES REPORT ──────────────────────────────────────────────  case 'sales_fuel':  // Fuel Sales — internal reconciliation only.  // Shows liters sold, computed revenue, and variance vs pump readings.  // No payment breakdown — that is merchandise-only.  // Real status values: 'Verified', 'Adjusted', 'Complete', 'completed', 'approved', 'Approved', 'validated', 'Validated'  $has_variance_table = false;  try {  $pdo->query("SELECT 1 FROM fuel_variance_reports LIMIT 1");  $has_variance_table = true;  } catch (Exception $e) { /* table doesn't exist yet */ }  $status_clause = "LOWER(TRIM(ft.status)) IN (  'verified','adjusted','complete','completed',  'approved','validated','verified sale'  )";  if ($has_variance_table) {  $stmt = $pdo->prepare("  SELECT  DATE(ft.transaction_date)  AS sale_date,  ft.fuel_type,  COUNT(ft.transaction_id)  AS txn_count,  COALESCE(SUM(ft.liters_sold), 0)  AS total_liters,  COALESCE(SUM(ft.total_amount), 0)  AS total_revenue,  COALESCE(AVG(fvr.variance_liters), 0) AS avg_variance_liters  FROM fuel_transactions ft  LEFT JOIN fuel_variance_reports fvr  ON  fvr.station_id = ft.station_id  AND DATE(fvr.report_date) = DATE(ft.transaction_date)  AND LOWER(TRIM(fvr.fuel_type)) = LOWER(TRIM(ft.fuel_type))  WHERE ft.station_id = ?  AND $status_clause  AND DATE(ft.transaction_date) BETWEEN ? AND ?  GROUP BY DATE(ft.transaction_date), ft.fuel_type  ORDER BY sale_date DESC, ft.fuel_type  ");  } else {  $stmt = $pdo->prepare("  SELECT  DATE(ft.transaction_date)  AS sale_date,  ft.fuel_type,  COUNT(ft.transaction_id)  AS txn_count,  COALESCE(SUM(ft.liters_sold), 0)  AS total_liters,  COALESCE(SUM(ft.total_amount), 0)  AS total_revenue,  0  AS avg_variance_liters  FROM fuel_transactions ft  WHERE ft.station_id = ?  AND $status_clause  AND DATE(ft.transaction_date) BETWEEN ? AND ?  GROUP BY DATE(ft.transaction_date), ft.fuel_type  ORDER BY sale_date DESC, ft.fuel_type  ");  }  $stmt->execute([$station_id, $date_from, $date_to]);  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  case 'sales_merchandise':  // Merchandise sales with payment breakdown and quantity.  // Date: use transaction_date if valid, else fall back to created_at (schema variation).  // validation_status values include Official/Completed/Approved/Verified/Adjusted.  // Include official records; exclude rejected/returned/cancelled/voided.  $merch_date_expr = "CASE WHEN mt.transaction_date > '2000-01-01' THEN DATE(mt.transaction_date) ELSE DATE(mt.created_at) END";  $stmt = $pdo->prepare("  SELECT  ($merch_date_expr)  AS sale_date,  COUNT(mt.id)  AS txn_count,  COALESCE(SUM(mt.total_amount), 0)  AS total_revenue,  COALESCE(SUM(CASE WHEN si.id IS NOT NULL THEN si.quantity ELSE 0 END), 0) AS total_quantity,  COALESCE(SUM(CASE WHEN LOWER(TRIM(mt.payment_method)) IN ('cash') THEN mt.total_amount ELSE 0 END), 0)  AS pay_cash,  COALESCE(SUM(CASE WHEN LOWER(TRIM(mt.payment_method)) IN ('credit card','card','debit card') THEN mt.total_amount ELSE 0 END), 0)  AS pay_card,  COALESCE(SUM(CASE WHEN LOWER(TRIM(mt.payment_method)) IN ('gcash','maya','paymaya','e-wallet','ewallet') THEN mt.total_amount ELSE 0 END), 0)  AS pay_ewallet,  COALESCE(SUM(CASE WHEN LOWER(TRIM(mt.payment_method)) IN ('e-fuel card','fuel card','efuel') THEN mt.total_amount ELSE 0 END), 0)  AS pay_efuel,  COALESCE(SUM(CASE WHEN LOWER(TRIM(mt.payment_method)) IN ('account receivable','credit','utang') THEN mt.total_amount ELSE 0 END), 0)  AS pay_credit  FROM merchandise_transactions mt  LEFT JOIN sale_items si ON si.sale_id = mt.id  WHERE mt.station_id = ?  AND ($merch_date_expr) BETWEEN ? AND ?  AND LOWER(TRIM(COALESCE(mt.validation_status,''))) NOT IN ('rejected','returned','cancelled','voided')  GROUP BY ($merch_date_expr)  ORDER BY sale_date DESC  ");  $stmt->execute([$station_id, $date_from, $date_to]);  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  case 'export_sales':  // ── Combined Sales Export (Fuel + Merchandise) ───────────────  require __DIR__ . '/_export_sales_handler.php';  exit; // handler calls exit itself, this is a safety net  // (old per-type export code removed — now handled by _export_sales_handler.php)  case 'sales_summary':  // Daily Summary Report - Consolidated daily snapshot for validation  $has_variance_table = false;  try {  $pdo->query("SELECT 1 FROM fuel_variance_reports LIMIT 1");  $has_variance_table = true;  } catch (Exception $e) { /* table doesn't exist yet */ }  $fuel_status_clause = "LOWER(TRIM(ft.status)) IN (  'verified','adjusted','complete','completed',  'approved','validated','verified sale'  )";  $merch_date_expr = "CASE WHEN mt.transaction_date > '2000-01-01' THEN DATE(mt.transaction_date) ELSE DATE(mt.created_at) END";  if ($has_variance_table) {  $stmt = $pdo->prepare("  SELECT  d.sale_date,  COALESCE(f.fuel_liters, 0) AS total_fuel_liters,  COALESCE(f.fuel_rev, 0) AS fuel_revenue,  COALESCE(m.merch_rev, 0) AS merch_revenue,  COALESCE(f.fuel_rev, 0) + COALESCE(m.merch_rev, 0) AS total_revenue,  COALESCE(f.avg_variance, 0) AS fuel_variance  FROM (  SELECT DISTINCT DATE(transaction_date) AS sale_date  FROM fuel_transactions  WHERE station_id = ? AND DATE(transaction_date) BETWEEN ? AND ?  AND $fuel_status_clause  UNION  SELECT DISTINCT ($merch_date_expr)  FROM merchandise_transactions  WHERE station_id = ? AND ($merch_date_expr) BETWEEN ? AND ?  AND LOWER(TRIM(COALESCE(validation_status,''))) NOT IN ('rejected','cancelled','voided')  ) d  LEFT JOIN (  SELECT  DATE(ft.transaction_date) AS sd,  COALESCE(SUM(ft.liters_sold), 0) AS fuel_liters,  COALESCE(SUM(ft.total_amount), 0) AS fuel_rev,  COALESCE(AVG(fvr.variance_liters), 0) AS avg_variance  FROM fuel_transactions ft  LEFT JOIN fuel_variance_reports fvr  ON fvr.station_id = ft.station_id  AND DATE(fvr.report_date) = DATE(ft.transaction_date)  AND LOWER(TRIM(fvr.fuel_type)) = LOWER(TRIM(ft.fuel_type))  WHERE ft.station_id = ?  AND $fuel_status_clause  AND DATE(ft.transaction_date) BETWEEN ? AND ?  GROUP BY DATE(ft.transaction_date)  ) f ON f.sd = d.sale_date  LEFT JOIN (  SELECT  ($merch_date_expr) AS sd,  COALESCE(SUM(total_amount), 0) AS merch_rev  FROM merchandise_transactions  WHERE station_id = ?  AND ($merch_date_expr) BETWEEN ? AND ?  AND LOWER(TRIM(COALESCE(validation_status,''))) NOT IN ('rejected','cancelled','voided')  GROUP BY ($merch_date_expr)  ) m ON m.sd = d.sale_date  ORDER BY d.sale_date DESC  ");  $stmt->execute([  $station_id, $date_from, $date_to,  $station_id, $date_from, $date_to,  $station_id, $date_from, $date_to,  $station_id, $date_from, $date_to  ]);  } else {  $stmt = $pdo->prepare("  SELECT  d.sale_date,  COALESCE(f.fuel_liters, 0) AS total_fuel_liters,  COALESCE(f.fuel_rev, 0) AS fuel_revenue,  COALESCE(m.merch_rev, 0) AS merch_revenue,  COALESCE(f.fuel_rev, 0) + COALESCE(m.merch_rev, 0) AS total_revenue,  0 AS fuel_variance  FROM (  SELECT DISTINCT DATE(transaction_date) AS sale_date  FROM fuel_transactions  WHERE station_id = ? AND DATE(transaction_date) BETWEEN ? AND ?  AND $fuel_status_clause  UNION  SELECT DISTINCT ($merch_date_expr)  FROM merchandise_transactions  WHERE station_id = ? AND ($merch_date_expr) BETWEEN ? AND ?  AND LOWER(TRIM(COALESCE(validation_status,''))) NOT IN ('rejected','cancelled','voided')  ) d  LEFT JOIN (  SELECT  DATE(ft.transaction_date) AS sd,  COALESCE(SUM(ft.liters_sold), 0) AS fuel_liters,  COALESCE(SUM(ft.total_amount), 0) AS fuel_rev  FROM fuel_transactions ft  WHERE ft.station_id = ?  AND $fuel_status_clause  AND DATE(ft.transaction_date) BETWEEN ? AND ?  GROUP BY DATE(ft.transaction_date)  ) f ON f.sd = d.sale_date  LEFT JOIN (  SELECT  ($merch_date_expr) AS sd,  COALESCE(SUM(total_amount), 0) AS merch_rev  FROM merchandise_transactions  WHERE station_id = ?  AND ($merch_date_expr) BETWEEN ? AND ?  AND LOWER(TRIM(COALESCE(validation_status,''))) NOT IN ('rejected','cancelled','voided')  GROUP BY ($merch_date_expr)  ) m ON m.sd = d.sale_date  ORDER BY d.sale_date DESC  ");  $stmt->execute([  $station_id, $date_from, $date_to,  $station_id, $date_from, $date_to,  $station_id, $date_from, $date_to,  $station_id, $date_from, $date_to  ]);  }  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  // ── 2. JOB ORDERS REPORT ─────────────────────────────────────────  case 'job_orders':  $status_filter = $_GET['status'] ?? $_POST['status'] ?? '';  $params = [$station_id, $date_from, $date_to];  $where_status = '';  if ($status_filter && $status_filter !== 'all') {  $where_status = ' AND (jo.status = ? OR jo.validation_status = ?)';  $params[] = $status_filter;  $params[] = $status_filter;  }  // Detect whether user_id column exists (some schemas have it, some don't)  $has_user_id = false;  try {  $pdo->query("SELECT user_id FROM job_orders LIMIT 0");  $has_user_id = true;  } catch (Exception $e) {}  $created_by_expr = $has_user_id  ? 'COALESCE(jo.created_by, jo.user_id)'  : 'jo.created_by';  // Detect whether mechanics table exists  $has_mechanics = false;  try {  $pdo->query("SELECT 1 FROM mechanics LIMIT 0");  $has_mechanics = true;  } catch (Exception $e) {}  if ($has_mechanics) {  // Check which name column mechanics table actually has  $mech_name_col = 'full_name';  try {  $pdo->query("SELECT full_name FROM mechanics LIMIT 0");  $mech_name_col = 'full_name';  } catch (Exception $e) {  try {  $pdo->query("SELECT name FROM mechanics LIMIT 0");  $mech_name_col = 'name';  } catch (Exception $e2) {  $mech_name_col = null;  }  }  $mechanic_join  = "LEFT JOIN mechanics mech ON mech.id = jo.assigned_mechanic_id";  $mechanic_field = $mech_name_col  ? "mech.{$mech_name_col} AS mechanic_name"  : "NULL AS mechanic_name";  } else {  $mechanic_join  = "";  $mechanic_field = "NULL AS mechanic_name";  }  $stmt = $pdo->prepare("  SELECT  jo.id,  jo.customer_name,  COALESCE(c.name, jo.customer_name, 'Walk-in') AS customer,  jo.service_type,  jo.service_description,  COALESCE(jo.status, jo.validation_status, 'Pending Validation') AS status,  jo.validation_status,  COALESCE(jo.estimated_cost, 0)  AS cost,  jo.created_at,  u.name  AS staff_name,  u.role  AS staff_role,  $mechanic_field  FROM job_orders jo  LEFT JOIN customers c  ON c.id  = jo.customer_id  LEFT JOIN users u  ON u.user_id  = $created_by_expr  $mechanic_join  WHERE jo.station_id = ?  AND DATE(jo.created_at) BETWEEN ? AND ?  $where_status  ORDER BY jo.created_at DESC  LIMIT 500  ");  $stmt->execute($params);  $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Status counts — check both status and validation_status  $cnt_stmt = $pdo->prepare("  SELECT  COALESCE(NULLIF(status,''), validation_status, 'Unknown') AS status,  COUNT(*) AS cnt,  COALESCE(SUM(estimated_cost), 0) AS total_cost  FROM job_orders  WHERE station_id = ? AND DATE(created_at) BETWEEN ? AND ?  GROUP BY COALESCE(NULLIF(status,''), validation_status, 'Unknown')  ");  $cnt_stmt->execute([$station_id, $date_from, $date_to]);  $counts = [];  foreach ($cnt_stmt->fetchAll(PDO::FETCH_ASSOC) as $r) {  $counts[strtolower($r['status'])] = [  'count'  => (int)$r['cnt'],  'total_cost' => (float)$r['total_cost'],  ];  }  ok(['rows' => $rows, 'counts' => $counts]);  // ── 3. CUSTOMER BALANCES REPORT ──────────────────────────────────  case 'customer_balances':  // Detect which column merchandise_transactions uses for customer reference  $mt_cust_col = null;  try {  $pdo->query("SELECT credit_customer_id FROM merchandise_transactions LIMIT 0");  $mt_cust_col = 'credit_customer_id';  } catch (Exception $e) {  try {  $pdo->query("SELECT customer_id FROM merchandise_transactions LIMIT 0");  $mt_cust_col = 'customer_id';  } catch (Exception $e2) {  $mt_cust_col = null;  }  }  // Detect which column customers uses for balance  $bal_col = 'balance';  try {  $pdo->query("SELECT credit_balance FROM customers LIMIT 0");  $bal_col = 'credit_balance';  } catch (Exception $e) {}  // Detect accounts_receivable table  $has_ar = false;  try { $pdo->query("SELECT 1 FROM accounts_receivable LIMIT 0"); $has_ar = true; } catch (Exception $e) {}  // Build subqueries safely  $credit_txn_count_field = $mt_cust_col  ? "(SELECT COUNT(*) FROM merchandise_transactions mt WHERE mt.{$mt_cust_col} = c.id AND LOWER(TRIM(mt.payment_method)) IN ('account receivable','credit','utang')) AS credit_txn_count"  : "0 AS credit_txn_count";  $last_credit_date_field = $mt_cust_col  ? "(SELECT COALESCE(MAX(CASE WHEN mt.transaction_date > '2000-01-01' THEN mt.transaction_date ELSE mt.created_at END), NULL) FROM merchandise_transactions mt WHERE mt.{$mt_cust_col} = c.id AND LOWER(TRIM(mt.payment_method)) IN ('account receivable','credit','utang')) AS last_credit_date"  : "NULL AS last_credit_date";  $ar_join = $has_ar  ? "LEFT JOIN (SELECT customer_id, MIN(due_date) AS due_date, status FROM accounts_receivable WHERE station_id = ? AND status IN ('Pending','Active') GROUP BY customer_id) ar ON ar.customer_id = c.id"  : "";  $ar_due  = $has_ar ? "ar.due_date" : "NULL";  $ar_status = $has_ar ? "COALESCE(ar.status, 'Active')" : "'Active'";  $params_bal = $has_ar ? [$station_id, $station_id] : [$station_id];  $stmt = $pdo->prepare("  SELECT  c.id,  c.name  AS customer_name,  COALESCE(c.{$bal_col}, 0)  AS outstanding_balance,  COALESCE(c.credit_limit, 0)  AS credit_limit,  CASE  WHEN COALESCE(c.credit_limit, 0) > 0  THEN ROUND((COALESCE(c.{$bal_col}, 0) / c.credit_limit) * 100, 1)  ELSE 0  END  AS usage_pct,  {$ar_due}  AS due_date,  {$ar_status}  AS ar_status,  {$credit_txn_count_field},  {$last_credit_date_field},  CASE  WHEN COALESCE(c.{$bal_col}, 0) = 0  THEN 'Settled'  WHEN COALESCE(c.{$bal_col}, 0) > COALESCE(c.credit_limit, 0) AND COALESCE(c.credit_limit, 0) > 0 THEN 'Over Limit'  WHEN {$ar_due} IS NOT NULL AND {$ar_due} < CURDATE()  THEN 'Overdue'  ELSE 'Active'  END  AS payment_status,  COALESCE(c.notes, c.mgr_notes, '')  AS remarks  FROM customers c  $ar_join  WHERE c.station_id = ?  ORDER BY outstanding_balance DESC  ");  $stmt->execute($params_bal);  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  // ── 4. DELIVERIES REPORT ─────────────────────────────────────────  case 'deliveries':  $status_filter = $_GET['status'] ?? $_POST['status'] ?? '';  // ── fuel_deliveries: uses received_by + verified_by ──────────  $rows = [];  try {  $params = [$station_id, $date_from, $date_to];  $ws = '';  if ($status_filter && $status_filter !== 'all') {  $ws = ' AND d.status = ?';  $params[] = $status_filter;  }  $stmt = $pdo->prepare("  SELECT  d.id,  d.delivery_date,  d.supplier,  d.invoice_no  AS reference_no,  d.fuel_type  AS product,  COALESCE(d.delivery_liters, 0)  AS quantity,  d.status,  d.notes  AS remarks,  d.created_at,  enc.name  AS encoded_by,  ver.name  AS validated_by,  'fuel'  AS source  FROM fuel_deliveries d  LEFT JOIN users enc ON enc.user_id = d.received_by  LEFT JOIN users ver ON ver.user_id = d.verified_by  WHERE d.station_id = ?  AND DATE(d.delivery_date) BETWEEN ? AND ?  $ws  ORDER BY d.delivery_date DESC  LIMIT 500  ");  $stmt->execute($params);  $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) { /* fuel_deliveries may not exist */ }  // ── deliveries_oversight: uses encoded_by + admin_id ─────────  $rows2 = [];  try {  $params2 = [$station_id, $date_from, $date_to];  $ws2 = '';  if ($status_filter && $status_filter !== 'all') {  $ws2 = ' AND do2.status = ?';  $params2[] = $status_filter;  }  $stmt2 = $pdo->prepare("  SELECT  do2.id,  do2.delivery_date,  do2.supplier,  COALESCE(do2.dr_number, do2.delivery_ref, do2.invoice_no) AS reference_no,  COALESCE(do2.product, do2.product_name)  AS product,  COALESCE(do2.quantity, 0)  AS quantity,  do2.status,  do2.remarks,  do2.created_at,  enc2.name  AS encoded_by,  adm.name  AS validated_by,  'oversight'  AS source  FROM deliveries_oversight do2  LEFT JOIN users enc2 ON enc2.user_id = do2.encoded_by  LEFT JOIN users adm  ON adm.user_id  = do2.admin_id  WHERE do2.station_id = ?  AND DATE(do2.delivery_date) BETWEEN ? AND ?  $ws2  ORDER BY do2.delivery_date DESC  LIMIT 500  ");  $stmt2->execute($params2);  $rows2 = $stmt2->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) { /* table may not exist */ }  // Merge both sources  $all_rows = array_merge($rows, $rows2);  // Sort merged by delivery_date DESC  usort($all_rows, fn($a, $b) => strcmp($b['delivery_date'] ?? '', $a['delivery_date'] ?? ''));  ok(['rows' => $all_rows]);  // ── 5. STAFF PERFORMANCE REPORT ──────────────────────────────────  case 'staff_performance':  // Detect user_id column in job_orders  $jo_user_id = false;  try { $pdo->query("SELECT user_id FROM job_orders LIMIT 0"); $jo_user_id = true; } catch (Exception $e) {}  $jo_created_expr = $jo_user_id ? 'COALESCE(jo.created_by, jo.user_id)' : 'jo.created_by';  // Detect deliveries_oversight table  $has_del_oversight = false;  try { $pdo->query("SELECT 1 FROM deliveries_oversight LIMIT 0"); $has_del_oversight = true; } catch (Exception $e) {}  $del_join = $has_del_oversight  ? "LEFT JOIN deliveries_oversight del ON del.encoded_by = u.id AND del.station_id = ? AND DATE(del.delivery_date) BETWEEN ? AND ?"  : "";  $del_count = $has_del_oversight  ? "COUNT(DISTINCT del.id) AS del_count,"  : "0 AS del_count,";  $params = [  $station_id, $date_from, $date_to,  // fuel  $station_id, $date_from, $date_to,  // merch  $station_id, $date_from, $date_to,  // job orders  $station_id, $date_from, $date_to,  // labor_sessions  ];  if ($has_del_oversight) {  $params[] = $station_id; $params[] = $date_from; $params[] = $date_to;  }  $params[] = $station_id; // WHERE u.station_id  $stmt = $pdo->prepare("  SELECT  u.id,  u.name,  u.role,  COUNT(DISTINCT ft.transaction_id)  AS fuel_txn_count,  COUNT(DISTINCT mt.id)  AS merch_txn_count,  COUNT(DISTINCT jo.id)  AS jo_count,  $del_count  COUNT(DISTINCT ls.id)  AS shift_count,  COALESCE(SUM(TIMESTAMPDIFF(MINUTE, ls.start_time, COALESCE(ls.end_time, NOW()))), 0)  AS total_minutes  FROM users u  LEFT JOIN fuel_transactions ft  ON ft.staff_id = u.id AND ft.station_id = ? AND DATE(ft.transaction_date) BETWEEN ? AND ?  LEFT JOIN merchandise_transactions mt  ON mt.staff_id = u.id AND mt.station_id = ? AND DATE(mt.transaction_date) BETWEEN ? AND ?  LEFT JOIN job_orders jo  ON ($jo_created_expr = u.id) AND jo.station_id = ? AND DATE(jo.created_at) BETWEEN ? AND ?  LEFT JOIN labor_sessions ls  ON ls.user_id = u.id AND ls.station_id = ? AND DATE(ls.start_time) BETWEEN ? AND ?  $del_join  WHERE u.station_id = ?  AND LOWER(u.role) IN ('staff','cashier','pump_attendant','mechanic')  AND u.status = 'Active'  GROUP BY u.id, u.name, u.role  ORDER BY (COUNT(DISTINCT ft.transaction_id) + COUNT(DISTINCT mt.id) + COUNT(DISTINCT jo.id)) DESC, u.name ASC  ");  $stmt->execute($params);  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  case 'staff_attendance':  $stmt = $pdo->prepare("  SELECT  u.name,  ls.shift_name,  DATE(ls.start_time)  AS work_date,  TIME(ls.start_time)  AS clock_in,  TIME(ls.end_time)  AS clock_out,  CASE  WHEN ls.end_time IS NOT NULL  THEN ROUND(TIMESTAMPDIFF(MINUTE, ls.start_time, ls.end_time) / 60.0, 2)  ELSE NULL  END  AS hours_worked  FROM labor_sessions ls  JOIN users u ON u.user_id = ls.user_id  WHERE ls.station_id = ?  AND DATE(ls.start_time) BETWEEN ? AND ?  ORDER BY ls.start_time DESC  LIMIT 500  ");  $stmt->execute([$station_id, $date_from, $date_to]);  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  // ── 6. VALIDATION LOGS ───────────────────────────────────────────  case 'validation_logs':  $type_filter = $_GET['type'] ?? $_POST['type'] ?? '';  $params = [$station_id, $date_from, $date_to];  $where_type = '';  if ($type_filter && $type_filter !== 'all') {  $where_type = " AND al.action LIKE ?";  $params[] = '%' . $type_filter . '%';  }  $stmt = $pdo->prepare("  SELECT  al.id,  al.created_at,  al.action,  al.details,  al.ip_address,  u.name  AS manager_name,  u.role  AS manager_role  FROM activity_logs al  LEFT JOIN users u ON u.user_id = al.user_id  WHERE (u.station_id = ? OR al.user_id IN (SELECT user_id FROM users WHERE station_id = ?))  AND DATE(al.created_at) BETWEEN ? AND ?  AND al.action IN (  'Approve','Reject','Adjust','Validate','Approve Transaction',  'Reject Transaction','Adjust Transaction','Approve Delivery',  'Reject Delivery','Approve Job Order','Reject Job Order',  'Validate Reading','Approve Reading','Reject Reading',  'Finalize Shift','Approve Inventory','Manager Action',  'RBAC Deny','Approve Stock Request','Reject Stock Request'  )  $where_type  ORDER BY al.created_at DESC  LIMIT 500  ");  $stmt->execute(array_merge([$station_id, $station_id], array_slice($params, 1)));  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  case 'validation_logs_all':  // All activity logs for manager/admin roles — includes Login, RBAC Deny, approvals, etc.  $stmt = $pdo->prepare("  SELECT  al.id,  al.created_at,  al.action,  al.details,  al.ip_address,  u.name  AS manager_name,  u.role  AS manager_role  FROM activity_logs al  LEFT JOIN users u ON u.user_id = al.user_id  WHERE u.station_id = ?  AND LOWER(u.role) IN ('manager','admin','superadmin','super admin')  AND DATE(al.created_at) BETWEEN ? AND ?  ORDER BY al.created_at DESC  LIMIT 1000  ");  $stmt->execute([$station_id, $date_from, $date_to]);  ok($stmt->fetchAll(PDO::FETCH_ASSOC));  // ── EXPORT: JOB ORDERS ───────────────────────────────────────────  case 'export_job_orders':  require __DIR__ . '/_export_job_orders_handler.php';  exit;  // ── EXPORT: CUSTOMER BALANCES ────────────────────────────────────  case 'export_balances':  require __DIR__ . '/_export_balances_handler.php';  exit;  // ── EXPORT: DELIVERIES ───────────────────────────────────────────  case 'export_deliveries':  require __DIR__ . '/_export_deliveries_handler.php';  exit;  // ── EXPORT: STAFF PERFORMANCE ────────────────────────────────────  case 'export_staff':  require __DIR__ . '/_export_staff_handler.php';  exit;  // ── EXPORT: VALIDATION LOGS ──────────────────────────────────────  case 'export_validation':  require __DIR__ . '/_export_validation_handler.php';  exit;  // ── DEBUG: check actual status values in DB ──────────────────────  case 'debug_sales':  $out = [];  try {  $s = $pdo->prepare("SELECT DISTINCT status, COUNT(*) AS cnt FROM fuel_transactions WHERE station_id=? GROUP BY status ORDER BY cnt DESC");  $s->execute([$station_id]);  $out['fuel_statuses'] = $s->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['fuel_statuses_err'] = $e->getMessage(); }  try {  $s = $pdo->prepare("SELECT DISTINCT validation_status, COUNT(*) AS cnt FROM merchandise_transactions WHERE station_id=? GROUP BY validation_status ORDER BY cnt DESC");  $s->execute([$station_id]);  $out['merch_statuses'] = $s->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['merch_statuses_err'] = $e->getMessage(); }  try {  $s = $pdo->prepare("SELECT MIN(transaction_date) AS min_date, MAX(transaction_date) AS max_date, COUNT(*) AS total FROM fuel_transactions WHERE station_id=?");  $s->execute([$station_id]);  $out['fuel_date_range'] = $s->fetch(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['fuel_date_range_err'] = $e->getMessage(); }  try {  $s = $pdo->prepare("SELECT MIN(CASE WHEN transaction_date > '2000-01-01' THEN transaction_date ELSE created_at END) AS min_date, MAX(CASE WHEN transaction_date > '2000-01-01' THEN transaction_date ELSE created_at END) AS max_date, COUNT(*) AS total FROM merchandise_transactions WHERE station_id=?");  $s->execute([$station_id]);  $out['merch_date_range'] = $s->fetch(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['merch_date_range_err'] = $e->getMessage(); }  $out['station_id']  = $station_id;  $out['date_from']  = $date_from;  $out['date_to']  = $date_to;  ok($out);  case 'debug_job_orders':  $out = ['station_id' => $station_id, 'date_from' => $date_from, 'date_to' => $date_to];  try {  $s = $pdo->prepare("SELECT DISTINCT status, COUNT(*) AS cnt FROM job_orders WHERE station_id=? GROUP BY status ORDER BY cnt DESC");  $s->execute([$station_id]);  $out['jo_statuses'] = $s->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['jo_statuses_err'] = $e->getMessage(); }  try {  $s = $pdo->prepare("SELECT DISTINCT validation_status, COUNT(*) AS cnt FROM job_orders WHERE station_id=? GROUP BY validation_status ORDER BY cnt DESC");  $s->execute([$station_id]);  $out['jo_validation_statuses'] = $s->fetchAll(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['jo_validation_err'] = $e->getMessage(); }  try {  $s = $pdo->prepare("SELECT MIN(created_at) AS min_date, MAX(created_at) AS max_date, COUNT(*) AS total FROM job_orders WHERE station_id=?");  $s->execute([$station_id]);  $out['jo_date_range'] = $s->fetch(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['jo_date_range_err'] = $e->getMessage(); }  try {  $s = $pdo->prepare("SELECT MIN(created_at) AS min_date, MAX(created_at) AS max_date, COUNT(*) AS total FROM job_orders");  $s->execute();  $out['jo_all_stations'] = $s->fetch(PDO::FETCH_ASSOC);  } catch (Exception $e) { $out['jo_all_err'] = $e->getMessage(); }  // Check if user_id column exists  try { $pdo->query("SELECT user_id FROM job_orders LIMIT 0"); $out['has_user_id'] = true; }  catch (Exception $e) { $out['has_user_id'] = false; }  // Check if mechanics table exists  try { $pdo->query("SELECT 1 FROM mechanics LIMIT 0"); $out['has_mechanics_table'] = true; }  catch (Exception $e) { $out['has_mechanics_table'] = false; }  ok($out);  default:  err('Unknown action: ' . htmlspecialchars($action));  }
} catch (Exception $e) {  err('Server error: ' . $e->getMessage(), 500);
}
